    {
      "вещество": "Калий (K)",
      "содержание": "≈ 2000–4000 мг/кг (сырой вес)",
      "влияние": "Поддерживает электролитный баланс, функцию сердца и проводимость нервно-мышечных сигналов."
    },
    {
      "вещество": "Фосфор (P)",
      "содержание": "≈ 500–1000 мг/кг (сырой вес)",
      "влияние": "Входит в состав АТФ, ДНК и костной ткани; необходим для энергетического метаболизма."
    },
    {
      "вещество": "Полисахариды (гликоген, β-глюканы)",
      "содержание": "неизвестно (в совокупности значительная доля сухого остатка)",
      "влияние": "β-глюканы могут модулировать иммунный ответ, стимулируя активность макрофагов и NK-клеток."
    },
    {
      "вещество": "Железо (Fe), цинк (Zn), медь (Cu)",
      "содержание": "Fe ≈ 5–15 мг/кг; Zn ≈ 20–60 мг/кг; Cu ≈ 2–5 мг/кг (сырой вес)",
      "влияние": "Микронутриенты: железо — переносчик кислорода, цинк и медь — кофакторы ферментов, антиоксидантная защита."
    }
  ]
}
